<script setup lang="ts">
import {ref,watch,onBeforeUnmount} from 'vue'
import ContentShell from '@/components/ContentShell.vue'
import SchemeReferences from '@/components/SchemeReferences.vue'
import {schemeBackups,type SchemeBackup} from '@/api/schemeBackups'
import {schemesApi,type OwnScheme,type SchemeInput} from '@/api/schemes'
import {useSession} from '@/stores/session'
import {useHead} from '@/lib/head'
useHead(()=>({title:'账号方案备份'}))
const session=useSession(),enabled=ref(false),status=ref('active'),items=ref<SchemeBackup[]>([]),own=ref<OwnScheme[]>([]),page=ref(1),total=ref(0),loading=ref(false),busy=ref(false),error=ref(''),message=ref(''),selected=ref(''),publish=ref<SchemeBackup|null>(null),ack=ref(false)
let sequence=0,disposed=false
const staged=new Map<number,{id:string;revision:number}>()
const text=(e:unknown)=>e instanceof Error?e.message:String(e)
function input(row:{title:string;summary?:string;items:SchemeBackup['items']}):SchemeInput{
 const refs=row.items.map(v=>{if(v.available!==true||!v.version||v.version<1)throw new Error('部分作品已不可用，请先更新方案引用');return{pack_id:v.pack_id,version:v.version}})
 return{title:row.title,summary:row.summary??'',items:refs}
}
async function load(){if(!enabled.value)return;const mine=++sequence;loading.value=true;error.value='';try{const data=await schemeBackups.list(page.value,status.value);if(!disposed&&mine===sequence){items.value=data.items;total.value=data.total}}catch(e){if(mine===sequence)error.value=text(e)}finally{if(mine===sequence)loading.value=false}}
async function act(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';message.value='';try{await fn()}catch(e){error.value=text(e)}finally{busy.value=false}}
async function toggle(){enabled.value=!enabled.value;publish.value=null;ack.value=false;if(enabled.value){await load();const mine=sequence;try{const data=await schemesApi.mine();if(!disposed&&enabled.value&&mine===sequence)own.value=data.items.filter(v=>v.status==='published')}catch(e){if(mine===sequence)error.value=text(e)}}else{++sequence;items.value=[];own.value=[];loading.value=false}}
async function backup(){const row=own.value.find(v=>String(v.id)===selected.value);if(!row)return;await act(async()=>{let target=staged.get(row.id);if(!target){target={id:crypto.randomUUID(),revision:0};staged.set(row.id,target)}const saved=await schemeBackups.save(target.id,input(row),target.revision);target.revision=saved.revision;status.value='active';page.value=1;await load();message.value='已备份选中方案的引用，备份仅自己可见。'})}
async function remove(row:SchemeBackup){if(!window.confirm(`将「${row.title}」移到云端回收站？本地副本和公开方案会保留。`))return;await act(async()=>{await schemeBackups.remove(row);await load();message.value='已移到回收站。'})}
async function restore(row:SchemeBackup){await act(async()=>{await schemeBackups.save(row.id,input(row),row.revision);await load();message.value='已恢复云端方案。'})}
async function publishNow(){const row=publish.value;if(!row||!ack.value)return;await act(async()=>{const saved=await schemesApi.publish(input(row));publish.value=null;ack.value=false;message.value=`已发布为公开方案 #${saved.id}。备份仍保留在账号中。`})}
watch([status,page],()=>{publish.value=null;ack.value=false;void load()})
watch(()=>session.user?.uid,()=>{enabled.value=false;++sequence;items.value=[];own.value=[];staged.clear();publish.value=null;selected.value='';message.value='';error.value='';loading.value=false;publish.value=null;ack.value=false})
onBeforeUnmount(()=>{disposed=true;++sequence})
</script>
<template><ContentShell><section class="backup-page"><div class="head"><div><p class="eyebrow">我的社区</p><h1>账号方案备份</h1></div><RouterLink class="btn" to="/me/works?tab=schemes">我的方案</RouterLink></div><p class="intro">保存自己选择的社区作品编号、固定版本、方案名称与简介。备份只对自己可见，不包含桌面文件、聊天、资料库和密钥。</p><section class="access panel"><div><h2>{{enabled?'本次云端访问已开启':'云端访问默认关闭'}}</h2><p>开启后读取账号备份；只有点击保存，才会写入所选方案。</p></div><button class="btn" :aria-pressed="enabled" :disabled="busy" @click="toggle">{{enabled?'关闭本次访问':'开启本次访问'}}</button></section><p v-if="error" class="notice error" role="alert">{{error}} <button v-if="enabled" class="btn btn-sm" @click="load">刷新重试</button></p><p v-if="message" class="notice" role="status">{{message}}</p><template v-if="enabled"><form class="save panel" @submit.prevent="backup"><label class="field"><span>选择自己的已发布方案</span><select v-model="selected" class="select" :disabled="busy"><option value="">请选择方案</option><option v-for="row in own" :key="row.id" :value="String(row.id)">{{row.title}}</option></select></label><button class="btn btn-primary" :disabled="busy||!selected">保存选中方案的备份</button><p v-if="!own.length">还没有已发布的方案。桌面应用也可以直接保存选中的社区作品引用。</p></form><nav class="tabs" aria-label="备份状态"><button :class="{active:status==='active'}" @click="status='active';page=1">云端方案</button><button :class="{active:status==='removed'}" @click="status='removed';page=1">回收站</button></nav><p v-if="loading" class="empty" role="status">正在读取…</p><p v-else-if="!items.length" class="empty">{{status==='removed'?'回收站是空的。':'还没有保存方案备份。'}}</p><article v-for="row in items" v-else :key="row.id" class="panel backup-card"><div class="head"><h2>{{row.title}}</h2><small>版本{{row.revision}} · {{new Date(row.updated_at).toLocaleString()}}</small></div><p v-if="row.summary">{{row.summary}}</p><SchemeReferences :items="row.items"/><div class="actions"><template v-if="status==='active'"><button class="btn btn-sm" :disabled="busy||row.items.some(v=>!v.available)" @click="publish=row;ack=false">发布为公开方案</button><button class="btn btn-sm" :disabled="busy" @click="remove(row)">移到回收站</button></template><button v-else class="btn btn-sm" :disabled="busy||row.items.some(v=>!v.available)" @click="restore(row)">恢复方案</button></div></article><section v-if="publish" class="publish panel" role="region" aria-label="确认公开方案"><h2>公开「{{publish.title}}」</h2><p>名称、简介和作品清单将对所有人可见。云端备份会保留。</p><label class="check"><input v-model="ack" type="checkbox">我确认公开以上方案内容</label><div class="actions"><button class="btn btn-primary" :disabled="busy||!ack" @click="publishNow">确认发布</button><button class="btn" :disabled="busy" @click="publish=null;ack=false">取消</button></div></section><div v-if="total>20" class="pager"><button class="btn" :disabled="loading||page<=1" @click="page--">上一页</button><span>第{{page}}页 · {{total}}份</span><button class="btn" :disabled="loading||page*20>=total" @click="page++">下一页</button></div></template></section></ContentShell></template>
<style scoped>.backup-page{padding:24px;max-width:960px;margin:auto}.head,.access,.save,.actions,.pager{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap}h1{font-size:24px;margin:4px 0}h2{font-size:16px;margin:0}.eyebrow,small,.intro,.access p,.save p{font-size:12px;color:var(--ink-3)}.eyebrow{margin:0}.intro{line-height:1.8;margin:18px 0 24px}.access,.save,.backup-card,.publish{padding:20px;margin-bottom:20px}.access p{margin:6px 0 0}.save .field{flex:1;min-width:220px}.save p{width:100%;margin:0}.tabs{display:flex;gap:24px;border-bottom:1px solid var(--line);margin:24px 0}.tabs button{padding:10px 0;border:0;border-bottom:2px solid transparent;background:none;color:var(--ink-3)}.tabs button.active{border-bottom-color:var(--brand);color:var(--ink);font-weight:600}.backup-card>.head{align-items:baseline}.backup-card>p{font-size:13px;color:var(--ink-2)}.actions{justify-content:flex-start;margin-top:16px}.notice{padding:14px 16px;border:1px solid var(--line);border-radius:8px}.error{color:var(--danger)}.empty{padding:32px 0;color:var(--ink-3)}.check{display:flex;gap:8px;align-items:center;font-size:13px}.pager{justify-content:center;font-size:12px}@media(max-width:600px){.backup-page{padding:18px}.access{align-items:flex-start}.head small{display:block}.save{align-items:stretch;flex-direction:column}}</style>
